SELECT w.id AS wallet_trade_id, w.execution_reason, o.symbol, o.decision AS one_m, o.atr_immediate_entry_allowed AS one_m_atr_ok, (SELECT CONCAT(v.id,'|',v.decision,'|',v.original_decision) FROM crypto_ai.trade_signal v WHERE v.symbol=o.symbol AND v.interval_code='5m' AND v.generated_at<=o.generated_at ORDER BY v.generated_at DESC LIMIT 1) AS five_used, CONCAT(f.id,'|',f.decision,'|',f.original_decision) AS five_hidden, p.id AS paper_id, p.realized_pnl, p.close_reason FROM crypto_ai.wallet_trade w JOIN crypto_ai.trade_signal o ON o.id=w.signal_id AND o.interval_code='1m' JOIN crypto_ai.trade_signal f ON f.symbol=o.symbol AND f.interval_code='5m' AND f.candle_open_time=o.candle_open_time - INTERVAL 4 MINUTE LEFT JOIN crypto_ai.paper_position p ON p.signal_id=w.signal_id WHERE w.side='BUY' AND w.executed_at >= '2026-10-11 00:00:00' AND f.generated_at > o.generated_at AND w.execution_reason <> 'SETUP_CONFIRMATION_WAKEUP' ORDER BY w.id LIMIT 40;